"use strict";(self.webpackChunkpersonal_blog=self.webpackChunkpersonal_blog||[]).push([["8322"],{62418(e,n,t){t.r(n),t.d(n,{metadata:()=>o,default:()=>d,frontMatter:()=>i,contentTitle:()=>s,toc:()=>c,assets:()=>l});var o=JSON.parse('{"id":"Zettelkasten/\u4EBA\u751F\u56DE\u62A5\u7387\u6700\u9AD8\u7684\u4E8B\u662F\u4EC0\u4E48","title":"\u4EBA\u751F\u56DE\u62A5\u7387\u6700\u9AD8\u7684\u4E8B\u662F\u4EC0\u4E48","description":"","source":"@site/knowledges/Zettelkasten/\u4EBA\u751F\u56DE\u62A5\u7387\u6700\u9AD8\u7684\u4E8B\u662F\u4EC0\u4E48.md","sourceDirName":"Zettelkasten","slug":"/Zettelkasten/\u4EBA\u751F\u56DE\u62A5\u7387\u6700\u9AD8\u7684\u4E8B\u662F\u4EC0\u4E48","permalink":"/zh-CN/knowledges/Zettelkasten/\u4EBA\u751F\u56DE\u62A5\u7387\u6700\u9AD8\u7684\u4E8B\u662F\u4EC0\u4E48","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{},"sidebar":"readings","previous":{"title":"zabbix \u90E8\u7F72","permalink":"/zh-CN/knowledges/Zettelkasten/zabbix \u90E8\u7F72"},"next":{"title":"\u672C\u5730\u542F\u52A8 etcd \u96C6\u7FA4","permalink":"/zh-CN/knowledges/Zettelkasten/\u672C\u5730\u542F\u52A8 etcd \u96C6\u7FA4"}}'),a=t(74848),r=t(28453);let i={},s,l={},c=[];function u(e){let n={code:"code",pre:"pre",...(0,r.R)(),...e.components};return(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:"\n\u6BCF\u5929\u8FD0\u52A8 30 \u5206\u949F \uFF08\u300A\u67F3\u53F6\u5200\u300B\uFF09\nExercise for 30 minutes every day(The Lancet)\n\n\u4FDD\u8BC1 7-9 \u5C0F\u65F6\u7684\u7761\u7720 \uFF08\u300A\u7761\u7720\u9769\u547D\u300B\uFF09\nGet 7\u20139 hours of sleep (The Sleep Revolution)\n\n\u6BCF\u5468\u8BFB\u5B8C\u4E00\u672C\u4E66\uFF08\u8036\u9C81\u5927\u5B66\uFF09 \nFinish one book per week(Yale University)\n\n\u6BCF\u5E74\u5B66\u4E60\u4E00\u4E2A\u65B0\u7684\u6280\u80FD \uFF08\u9A6C\u666E\u7814\u7A76\u6240\uFF09\nLearn a new skill every year(Max Planck Institute)\n\n\u65E9\u6668\u575A\u6301\u51A5\u60F3 20 \u5206\u949F \uFF08\u9EBB\u7701\u603B\u533B\u9662\uFF09\nMeditate for 20 minutes every morning(Massachusetts General Hospital)\n\n\u591A\u5403\u5F69\u8272\u852C\u679C \uFF08\u65B0\u82F1\u683C\u5170\u6742\u5FD7\uFF09\nEat more colorful fruits and vegetables(New England Journal of Medicine)\n\n\u7761\u524D\u8FDB\u884C\u6BCF\u65E5\u590D\u76D8 \uFF08\u52A0\u5DDE\u5927\u5B66\uFF09\nDo a daily reflection before bed (University of California)\n\n\u5DE5\u8D44\u5B58 20\uFF05 \uFF08\u5DF4\u83F2\u7279\uFF09\nSave 20% of your salary(Warren Buffett)\n\n\u628A\u76EE\u6807\u8D34\u5728\u51B0\u7BB1\u4E0A \uFF08\u591A\u7C73\u5C3C\u52A0\u5927\u5B66\uFF09\nPut your goals on the refrigerator(Dominican University)\n\n\u751F\u6C14\u65F6\u5148\u9ED8\u657010\u79D2\u518D\u8BF4\u8BDD \uFF08\u5361\u8010\u57FA\u57FA\u91D1\u4F1A\uFF09\nWhen angry, silently count to 10 seconds before speaking  (Carnegie Foundation)\n\n\u624B\u673A\u8C03\u4E3A\u9ED1\u767D\u6A21\u5F0F \uFF08\u65AF\u5766\u798F\u6CE8\u610F\u529B\u7814\u7A76\u6240\uFF09\nSet your phone to grayscale mode(Stanford Attention Research Institute)\n\n\u5199\u6BCF\u5468\u603B\u7ED3 \uFF08\u6C83\u987F\u5546\u5B66\u9662\uFF09\nWrite a weekly summary(Wharton School)\n\n\u538B\u529B\u5927\u7684\u65F6\u5019\u5199\u6D41\u6C34\u8D26 \uFF08\u521B\u4F24\u6CBB\u7597\u4E13\u5BB6\uFF09\nWhen stressed, write stream-of-consciousness notes(Trauma therapy experts)\n\n\u665A\u4E0A\u624B\u673A\u653E\u8FDC\u79BB\u81EA\u5DF1\u7684\u5730\u65B9 \uFF08\u5BBE\u5927\u884C\u4E3A\u5B9E\u9A8C\u5BA4\uFF09\nKeep your phone away from you at night(UPenn Behavioral Lab)\n\n\u6BCF\u5929\u559D\u8DB3\u591F\u7684\u6C34\uFF082-3 \u5347\uFF09 \uFF08\u300A\u82F1\u56FD\u8425\u517B\u5B66\u6742\u5FD7\u300B\uFF09\nDrink enough water daily (2\u20133 liters)(British Journal of Nutrition)\n\n\u5B9A\u671F\u8FDB\u884C\u6DF1\u547C\u5438\u7EC3\u4E60 \uFF08\u54C8\u4F5B\u533B\u5B66\u9662\uFF09\nPractice deep breathing regularly (Harvard Medical School)\n\n\u6BCF\u5929\u665215\u5206\u949F\u592A\u9633\uFF0C\u6539\u5584\u7EF4\u751F\u7D20 D \u6C34\u5E73 \uFF08\u300A\u81EA\u7136\u300B\u671F\u520A\uFF09\nGet 15 minutes of sunlight daily to improve vitamin D levels(Nature)\n\n\u6BCF\u5468\u4E0E\u5BB6\u4EBA\u5171\u8FDB\u665A\u9910\u4E09\u6B21 \uFF08\u54E5\u4F26\u6BD4\u4E9A\u5927\u5B66\uFF09\nHave dinner with family three times a week(Columbia University)\n\n\u5B66\u4E60\u4E00\u95E8\u4E50\u5668 \uFF08\u300A\u795E\u7ECF\u79D1\u5B66\u524D\u6CBF\u300B\uFF09\nLearn a musical instrument(Frontiers in Neuroscience)\n\n\u6BCF\u5929\u6574\u7406\u623F\u95F4 10 \u5206\u949F \uFF08\u300A\u4EBA\u683C\u4E0E\u793E\u4F1A\u5FC3\u7406\u5B66\u6742\u5FD7\u300B\uFF09\nSpend 10 minutes tidying your room daily(Journal of Personality and Social Psychology)\n\n\u6BCF\u5468\u505A\u4E00\u6B21 \u201C\u6570\u5B57\u65AD\u820D\u79BB\u201D\uFF08\u51CF\u5C11\u5C4F\u5E55\u65F6\u95F4\uFF09 \u300A\u884C\u4E3A\u533B\u5B66\u5E74\u9274\u300B\uFF09\nDo a weekly \u201Cdigital detox\u201D to reduce screen time\uFF08(Annals of Behavioral Medicine)\n\n\u6BCF\u5929\u5938\u8D5E\u4E00\u4E2A\u4EBA \uFF08\u300A\u79EF\u6781\u5FC3\u7406\u5B66\u6742\u5FD7\u300B\uFF09\nCompliment someone every day (Journal of Positive Psychology)\n\n\u5B9A\u671F\u590D\u76D8\u804C\u4E1A\u89C4\u5212 \uFF08\u9EA6\u80AF\u9521\u7814\u7A76\uFF09\nRegularly review your career plan (McKinsey Research)\n\n\u57F9\u517B\u4E00\u4E2A\u4E0D\u82B1\u94B1\u7684\u7231\u597D \uFF08\u300A\u5E78\u798F\u7814\u7A76\u6742\u5FD7\u300B\uFF09\nCultivate a no-cost hobby (Journal of Happiness Studies)\n\n\u6BCF\u5468\u7ED9\u81EA\u5DF1 2 \u5C0F\u65F6 \u201C\u72EC\u5904\u65F6\u95F4\u201D \uFF08\u300A\u5FC3\u7406\u79D1\u5B66\u300B\uFF09\nGive yourself 2 hours of \u201Calone time\u201D each week(Psychological Science)\n\n\u62D2\u7EDD\u65E0\u610F\u4E49\u7684\u793E\u4EA4 \uFF08\u300A\u793E\u4F1A\u5FC3\u7406\u5B66\u6742\u5FD7\u300B\uFF09\nDecline meaningless social activities (Journal of Social Psychology)\n\n\u5B66\u4E60\u57FA\u7840\u7406\u8D22\u77E5\u8BC6 \uFF08\u7F8E\u8054\u50A8\u7ECF\u6D4E\u7814\u7A76\uFF09\nLearn basic financial literacy (Federal Reserve Economic Research)\n\n\u7EC3\u4E60\u201C5 \u79D2\u6CD5\u5219\u201D \u514B\u670D\u62D6\u5EF6 \uFF08\u6885\u5C14\u30FB\u7F57\u5BBE\u65AF\u7814\u7A76\uFF09\nPractice the \u201C5-Second Rule\u201D to overcome procrastination (Mel Robbins research)\n\n\u5B9A\u671F\u68C0\u67E5\u4F60\u7684\u8EAB\u4F53\u6307\u6807 \uFF08\u300A\u67F3\u53F6\u5200\u30FB\u516C\u5171\u536B\u751F\u300B\uFF09\nRegularly check your health indicators (The Lancet Public Health)\n\n\u4E0E\u79EF\u6781\u7684\u4EBA\u591A\u76F8\u5904 \uFF08\u60C5\u7EEA\u4F20\u67D3\u7406\u8BBA\uFF09\uFF08\u300A\u81EA\u7136\u30FB\u4EBA\u7C7B\u884C\u4E3A\u300B\uFF09\nSpend more time with positive people(Emotional Contagion Theory) (Nature Human Behaviour)\n\n\u6BCF\u5929\u5B66\u4E00\u53E5\u5916\u8BED \uFF08\u300A\u5927\u8111\u4E0E\u8BED\u8A00\u300B\uFF09\nLearn one sentence in a foreign language daily(Brain and Language)\n\n\u7761\u524D 1 \u5C0F\u65F6\u4E0D\u8BA8\u8BBA\u4E25\u8083\u8BDD\u9898\uFF08\u63D0\u9AD8\u7761\u7720\u8D28\u91CF\uFF09\uFF08\u300A\u7761\u7720\u533B\u5B66\u8BC4\u8BBA\u300B\uFF09\nAvoid serious discussions one hour before bedtime to improve sleep quality(Sleep Medicine Reviews)\n\n"})})}function d(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}},28453(e,n,t){t.d(n,{R:()=>i,x:()=>s});var o=t(96540);let a={},r=o.createContext(a);function i(e){let n=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(r.Provider,{value:n},e.children)}}}]);